using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class EchoAudienceChecks {
 static readonly BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Require(bool ok,string message){if(!ok)throw new Exception(message);}
 public static void VerifyModel(){var old=JsonUtility.FromJson<EchoMemory>("{\"demonstrations\":1,\"games\":1}");Require(old.Valid()&&old.audienceVisits==0,"Historical echoes rejected");old.audienceVisits=3;Require(!old.Valid(),"More than two listeners per echo accepted");var social=new SocialMemory();Require(social.RememberMusic(false,0,1)&&social.musicGatherings==1&&!social.RememberMusic(false,0,2),"Music memory duplicated or failed");Require(social.Valid(),"Music preferences invalid");Debug.Log("BWVR_ECHO_AUDIENCE_MODEL_PASS: legacy history, bounded visits, cooldown and social memory");}
 public static void Verify(Action<PlayerRhythm,VillagerExploration[]> capture=null){
  Require(Application.isPlaying,"Enter Play mode");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();slice.SetSanctuaryOpen(false);var god=slice.GetComponentInChildren<CreatureHybrid>();var music=slice.GetComponentInChildren<PlayerRhythm>();var people=slice.GetComponentsInChildren<VillagerExploration>();var nav=god.GetComponent<IslandNavigator>();var lane=slice.GetComponentInChildren<BeachBall>().Bowling;var field=typeof(QuestSlice).GetField("state",Flags);var original=(SliceState)field.GetValue(slice);var gp=god.transform.position;var gr=god.transform.rotation;var tp=music.transform.position;var tr=music.transform.rotation;var positions=people.Select(p=>p.transform.position).ToArray();var rotations=people.Select(p=>p.transform.rotation).ToArray();GameObject blocker=null;var test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true,water=100,crops=100,hunger=.1f,playPreference=1};test.Weather.rain=0;field.SetValue(slice,test);god.NewSeason();var cooldowns=god.Targets.Where(t=>t.affordance!=null).ToDictionary(t=>t.affordance,t=>t.affordance.cooldown);var prop=music.GetComponent<CreatureAffordance>();var pair=people.Take(2).ToArray();int[] before=new int[2];
  void Stage(){god.Interrupt("Audience staging");music.ResetWorld();Require(nav.world.Sample(lane.Start,nav.profile,5,out var start),"No creature start");god.transform.position=nav.world.ProjectFoot(start,nav.profile);god.transform.rotation=Quaternion.LookRotation(lane.Forward);nav.ResetRoute();music.transform.position=nav.world.Terrain.Project(lane.Start+lane.Forward*12*nav.world.Scale)+Vector3.up*nav.world.Scale*.25f;music.transform.rotation=Quaternion.LookRotation(lane.Forward);var palette=slice.GetComponentInChildren<GodToolPalette>();palette.Cancel();palette.Process(new Ray(Camera.main.transform.position,Camera.main.transform.forward),false,true,false,.05f,false);
   for(int i=0;i<people.Length;i++){var person=people[i];person.GetComponent<VillagerSocial>().ResetTask();person.ResetTask();person.GetComponent<VillagerBlockPlay>().ResetTask();person.GetComponent<VillagerResourceGathering>().Cancel();slice.GetComponentInChildren<VillageFamilies>()?.Release(person.GetComponent<VillagerRoutine>());slice.GetComponentInChildren<VillageCathedral>()?.Cancel(person.GetComponent<VillagerRoutine>());person.GetComponent<CarryItem>().held=false;var social=test.Social(i);social.musicInterest=.8f;social.boldness=.8f;social.nextMusicAt=0;social.injury=i>=2?1:0;if(i<2){var wanted=music.transform.position+lane.Forward*6*nav.world.Scale+lane.Right*(i==0?8:-8)*nav.world.Scale;var walker=person.GetComponent<IslandNavigator>();Require(nav.world.Sample(wanted,walker.profile,3,out var at),"No listener start");person.transform.position=nav.world.ProjectFoot(at,walker.profile);person.transform.LookAt(new Vector3(music.transform.position.x,person.transform.position.y,music.transform.position.z));walker.ResetRoute();}}
   foreach(var a in cooldowns.Keys)if(a!=prop)a.cooldown=test.Hybrid.time+200;
  }
  void Record(){foreach(var note in new[]{0,1,0,1}){test.Hybrid.time+=.4f;Require(music.Tap(note),"Player note failed");}}
  try{
   Stage();Record();var first=pair[0];var eye=first.transform.position+Vector3.up*nav.world.Scale*first.GetComponent<IslandNavigator>().profile.height*.8f;var end=music.GetComponent<Collider>().bounds.center;blocker=GameObject.CreatePrimitive(PrimitiveType.Cube);blocker.name="Audience sight blocker QA";blocker.transform.position=(eye+end)*.5f;blocker.transform.localScale=Vector3.one*nav.world.Scale*3;Physics.SyncTransforms();Require(!first.TryWatchEcho(music),"Occluded listener joined");UnityEngine.Object.DestroyImmediate(blocker);blocker=null;music.Advance(.05f);Require(music.AudienceCount==2&&pair.All(p=>p.EchoAudience),"Nearby free villagers did not join: "+music.AudienceCount);Require(pair.All(p=>p.GetComponentInChildren<HumanoidHands>().resource==null),"Listener retained carried load");Require(people.Skip(2).All(p=>!p.EchoAudience),"Injured villagers recruited");
   bool clapped=false,paused=false,captured=false;for(int i=0;i<700&&test.WorldPlay.Echo.games==0;i++){foreach(var person in pair)person.Tick(.05f,false);god.Tick(.05f);music.Advance(.05f);clapped|=pair.Any(p=>p.GetComponentInChildren<HumanoidHands>().clap>0);if(music.Active&&music.Played>=2&&!paused){var at=pair.Select(p=>p.transform.position).ToArray();int notes=music.Played;test.paused=true;foreach(var person in pair)person.Tick(1,true);god.Tick(1);music.Advance(1);Require(music.Played==notes&&pair.Select(p=>p.transform.position).SequenceEqual(at),"Paused audience moved / played");test.paused=false;paused=true;}if(pair.Any(p=>p.GetComponentInChildren<HumanoidHands>().clap>.85f)&&!captured){captured=true;capture?.Invoke(music,pair);}}
   Require(clapped&&paused&&test.WorldPlay.Echo.games==1&&test.WorldPlay.Echo.audienceVisits==2,"Audience did not clap/witness exactly one echo: visits="+test.WorldPlay.Echo.audienceVisits+" beats="+string.Join(",",pair.Select(p=>p.EchoBeats)));Require(music.AudienceCount==0&&pair.All(p=>p.GetComponentInChildren<HumanoidHands>().clap==0),"Completed audience retained slots / hand pose");for(int i=0;i<2;i++){var m=test.Social(i);Require(m.musicGatherings==1&&m.musicInterest>.8f&&m.trust>.45f,"Listener memory / sentiment missing");var bond=m.Peer(pair[1-i].GetComponent<HybridTarget>().id);Require(bond!=null&&bond.good==1,"Co-listeners did not form a peer memory");before[i]=m.musicGatherings;}Require(test.Hybrid.receipt.echoed&&test.Hybrid.receipt.partner.Length==0,"Spectator credited as performer");music.Cancel(true);Require(test.WorldPlay.Echo.audienceVisits==2&&pair.All(p=>p.WitnessEcho(music)<0),"Duplicate listener credit");Require(JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test)).Valid(),"Audience save invalid");
   Stage();Record();music.Advance(.05f);Require(music.AudienceCount==2,"Second circle failed");pair[0].GetComponent<CarryItem>().held=true;pair[0].Tick(.05f,false);Require(music.AudienceCount==1&&!pair[0].EchoAudience,"Picked-up listener retained slot");pair[0].GetComponent<CarryItem>().held=false;prop.Item.held=true;music.Advance(.05f);prop.Item.held=false;Require(music.AudienceCount==0&&pair.All(p=>!p.EchoAudience)&&test.WorldPlay.Echo.audienceVisits==2,"Instrument pickup retained circle / granted rewards");
   Stage();Record();music.Advance(.05f);test.Hybrid.time+=26;music.Advance(.05f);Require(music.AudienceCount==0&&pair.All(p=>!p.EchoAudience)&&test.WorldPlay.Echo.games==1&&test.WorldPlay.Echo.audienceVisits==2,"Expired invitation retained audience / rewarded");Require(test.Social(0).musicGatherings==before[0]&&test.Social(1).musicGatherings==before[1],"Canceled listeners gained visits");Debug.Log("BWVR_ECHO_AUDIENCE_PLAY_PASS: two visible healthy villagers route to separate spots, clap on creature notes, freeze with pause, gain once-only enjoyment/peer/creature bonds and save; occlusion/injury exclusion, pickup, expiration and pose/slot cleanup passed");
  }finally{if(blocker!=null)UnityEngine.Object.DestroyImmediate(blocker);music.GetComponent<CarryItem>().held=false;music.Cancel();foreach(var person in people){person.GetComponent<CarryItem>().held=false;person.ResetTask();}god.Interrupt("Audience QA complete");field.SetValue(slice,original);god.NewSeason();foreach(var c in cooldowns)c.Key.cooldown=c.Value;for(int i=0;i<people.Length;i++){people[i].transform.SetPositionAndRotation(positions[i],rotations[i]);people[i].GetComponent<IslandNavigator>().ResetRoute();}god.transform.SetPositionAndRotation(gp,gr);nav.ResetRoute();music.transform.SetPositionAndRotation(tp,tr);}
 }
}
}
